/bin/bash -lc "cd runs; python3 -c '
import json,glob,re,os
for f in sorted(glob.glob(\"*/executor-events.jsonl\"))+sorted(glob.glob(\"../runs-aborted/*/executor-events.jsonl\")):
    cmds=[]
    for l in open(f):
        try:e=json.loads(l)
        except: continue
        if e.get(\"type\")==\"item.completed\" and e[\"item\"][\"type\"]==\"command_execution\":
            cmds.append(e[\"item\"][\"command\"])
    paths=set()
    for c in cmds:
        for p in re.findall(r\"(?<"'!['"\\w"'$])(/[A-Za-z0-9_./-]+)",c):
            paths.add(p)
    odd=sorted(p for p in paths if not re.match(r"''^/(opt/pf83/(packet|bin|pkg)|bin/(bash|sh|cat|ls|echo|sleep|date)|usr/bin/|dev/null)",p))
    print(f,len(cmds),"odd:",odd[:60])
'"'"

