import json
ev=[]
for l in open(\"actions.jsonl\"):
    a=json.loads(l)
    if \"executed\" in a: ev.append((a[\"time_ns\"],\"A\",a))
for l in open(\"screens.jsonl\"):
    s=json.loads(l); ev.append((s[\"time_ns\"],\"S\",s))
ev.sort(key=lambda x:x[0])
for t,k,x in ev:
    ts=x[\"utc\"][11:19]
    if k==\"A\":
        d={kk:v for kk,v in x.items() if kk in(\"executed\",\"key\",\"text\",\"pattern\",\"matched\")}
        if \"text\" in d: d[\"text\"]=d[\"text\"][:90]
        print(ts,\"ACT\",d)
    else:
        sc=x[\"screen\"]; lines=sc.split(\"\\n\")
        tag=\"\"
        if \"Enable full access?\" in sc:
            cur=[l.strip()[:40] for l in lines if l.strip().startswith(\"›\") and (\"Yes, continue\" in l or \"Cancel\" in l)]
            tag=\"WARN cursor=\"+str(cur)
        elif \"Update Model Permissions\" in sc:
            cur=[l.strip()[:40] for l in lines if l.strip().startswith(\"›\") and l.strip()[2:3].isdigit()]
            curr=[l.strip()[:40] for l in lines if \"(current)\" in l]
            tag=\"PICKER cursor=%s current=%s\"%(cur,curr)
        msgs=[l.strip()[:70] for l in lines if \"Permissions applied\" in l or \"Permissions requested\" in l]
        print(ts,\"SCR\",x[\"label\"],tag,\"| perms-msgs:\",len(msgs), \"| working\" if \"Working\" in sc else \"\")
' | cut -c1-230"

