import json,sys
run=sys.argv[1]
ev=[]
for l in open(run+\"/collected/evidence/actions.jsonl\"):
    a=json.loads(l)
    if \"executed\" in a: ev.append((a[\"time_ns\"],\"A\",a))
for l in open(run+\"/collected/evidence/screens.jsonl\"):
    s=json.loads(l); ev.append((s[\"time_ns\"],\"S\",s))
for l in open(run+\"/collected/evidence/fixture.jsonl\"):
    s=json.loads(l); ev.append((s[\"time_ns\"],\"F\",s))
ev.sort(key=lambda x:x[0])
for t,k,x in ev:
    ts=x[\"utc\"][11:19]
    if k==\"A\":
        d={kk:v for kk,v in x.items() if kk in(\"executed\",\"key\",\"text\",\"matched\")}
        if \"text\" in d: d[\"text\"]=d[\"text\"][:110]
        print(ts,\"ACT\",d)
    elif k==\"F\":
        print(ts,\"FIX\",x[\"label\"],{kk:v[:120] for kk,v in x[\"files\"].items() if kk"'!="input.txt"})
    else:
        sc=x["screen"]; lines=sc.split("'"\\n\")
        tag=\"\"
        if \"Enable full access?\" in sc:
            tag=\"WARN cursor=\"+str([l.strip()[:20] for l in lines if l.strip().startswith(\"›\") and (\"Yes, continue\" in l or \"Cancel\" in l)])
        elif \"Update Model Permissions\" in sc:
            tag=\"PICKER cur=%s current=%s\"%([l.strip()[:22] for l in lines if l.strip().startswith(\"›\") and l.strip()[2:3].isdigit()],[l.strip()[:28] for l in lines if \"(current)\" in l])
        if \"Would you like to run\" in sc: tag+=\" APPROVAL-PROMPT\"
        w=[l.strip()[:40] for l in lines if \"Working (\" in l]
        print(ts,\"SCR\",x[\"label\"],tag,w)
' F06 | cut -c1-260"

